from __future__ import annotations

from pathlib import Path


def replace_once(text: str, old: str, new: str, label: str) -> str:
    if text.count(old) != 1:
        raise SystemExit(f"{label}: expected exactly one anchor, found {text.count(old)}")
    return text.replace(old, new, 1)


py_path = Path("entroly/work_graph_store.py")
py = py_path.read_text(encoding="utf-8")
py = replace_once(py, "import socket\n", "import socket\nimport stat as statmod\n", "python stat import")
py = replace_once(
    py,
    "DEFAULT_MAX_STATE_BYTES = 64 * 1024 * 1024\n",
    "DEFAULT_MAX_STATE_BYTES = 64 * 1024 * 1024\nMAX_LOCK_FILE_BYTES = 4096\n",
    "python lock bound",
)
old = '''    def _lock_token(self) -> str:\n        try:\n            if self.lock_path.is_symlink():\n                raise WorkGraphStateError(f"unsafe Work Graph lock path: {self.lock_path}")\n            return self.lock_path.read_text(encoding="utf-8").split("\\n", 1)[0]\n        except FileNotFoundError:\n            return ""\n        except OSError:\n            return ""\n'''
new = '''    def _read_regular_file_bounded(self, path: Path, max_bytes: int, label: str) -> bytes | None:\n        """Read one stable regular file through the descriptor that was verified.\n\n        The path is lstat'd only to establish an expected identity. The actual\n        bytes are read from a no-follow descriptor where supported, and the\n        inode/size/timestamps are checked before and after the read. This keeps\n        lock/state reads from following a swapped symlink or accepting a file\n        that changed underneath the reader.\n        """\n\n        try:\n            before_path = path.lstat()\n        except FileNotFoundError:\n            return None\n        except OSError as exc:\n            raise WorkGraphStateError(f"cannot inspect Work Graph {label}: {exc}") from exc\n        if not statmod.S_ISREG(before_path.st_mode):\n            raise WorkGraphStateError(f"unsafe Work Graph {label}: {path}")\n\n        flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)\n        try:\n            fd = os.open(path, flags)\n        except FileNotFoundError:\n            return None\n        except OSError as exc:\n            raise WorkGraphStateError(f"cannot open Work Graph {label} safely: {exc}") from exc\n        try:\n            before_fd = os.fstat(fd)\n            if (before_fd.st_dev, before_fd.st_ino) != (before_path.st_dev, before_path.st_ino):\n                raise WorkGraphStateError(f"Work Graph {label} changed while opening: {path}")\n            if not statmod.S_ISREG(before_fd.st_mode):\n                raise WorkGraphStateError(f"unsafe Work Graph {label}: {path}")\n            if before_fd.st_size > max_bytes:\n                raise WorkGraphStateError(\n                    f"Work Graph {label} is {before_fd.st_size} bytes; limit is {max_bytes}"\n                )\n\n            payload = bytearray()\n            while len(payload) <= max_bytes:\n                chunk = os.read(fd, min(1024 * 1024, max_bytes + 1 - len(payload)))\n                if not chunk:\n                    break\n                payload.extend(chunk)\n            if len(payload) > max_bytes:\n                raise WorkGraphStateError(f"Work Graph {label} exceeds {max_bytes} bytes")\n\n            after_fd = os.fstat(fd)\n            if (\n                after_fd.st_dev != before_fd.st_dev\n                or after_fd.st_ino != before_fd.st_ino\n                or after_fd.st_size != before_fd.st_size\n                or after_fd.st_mtime_ns != before_fd.st_mtime_ns\n                or after_fd.st_ctime_ns != before_fd.st_ctime_ns\n            ):\n                raise WorkGraphStateError(f"Work Graph {label} changed during read: {path}")\n            try:\n                after_path = path.lstat()\n            except OSError as exc:\n                raise WorkGraphStateError(f"Work Graph {label} changed during read: {path}") from exc\n            if (after_path.st_dev, after_path.st_ino) != (before_fd.st_dev, before_fd.st_ino):\n                raise WorkGraphStateError(f"Work Graph {label} path changed during read: {path}")\n            return bytes(payload)\n        finally:\n            os.close(fd)\n\n    def _lock_token(self) -> str:\n        payload = self._read_regular_file_bounded(self.lock_path, MAX_LOCK_FILE_BYTES, "lock")\n        if payload is None:\n            return ""\n        try:\n            return payload.decode("utf-8").split("\\n", 1)[0]\n        except UnicodeDecodeError as exc:\n            raise WorkGraphStateError("Work Graph lock is not valid UTF-8") from exc\n\n    @staticmethod\n    def _local_lock_owner_alive(token: str) -> bool:\n        parts = token.rsplit(":", 2)\n        if len(parts) != 3 or parts[0] != socket.gethostname():\n            return False\n        try:\n            pid = int(parts[1])\n        except ValueError:\n            return False\n        if pid <= 0:\n            return False\n        if pid == os.getpid():\n            return True\n        try:\n            os.kill(pid, 0)\n        except ProcessLookupError:\n            return False\n        except PermissionError:\n            return True\n        except OSError:\n            return False\n        return True\n'''
py = replace_once(py, old, new, "python safe lock read")
old = '''    def _stale_lock(self) -> bool:\n        try:\n            stat = self.lock_path.lstat()\n        except FileNotFoundError:\n            return False\n        except OSError:\n            return False\n        if self.lock_path.is_symlink() or not self.lock_path.is_file():\n            raise WorkGraphStateError(f"unsafe Work Graph lock path: {self.lock_path}")\n        first = stat.st_mtime\n        if self._filesystem_now() - first < self.stale_lock_seconds:\n            return False\n        time.sleep(DEFAULT_LOCK_SETTLE_SECONDS)\n        try:\n            second = self.lock_path.stat().st_mtime\n        except OSError:\n            return False\n        return second == first and self._filesystem_now() - second >= self.stale_lock_seconds\n'''
new = '''    def _stale_lock(self) -> bool:\n        try:\n            first_stat = self.lock_path.lstat()\n        except FileNotFoundError:\n            return False\n        except OSError:\n            return False\n        if not statmod.S_ISREG(first_stat.st_mode):\n            raise WorkGraphStateError(f"unsafe Work Graph lock path: {self.lock_path}")\n        if self._filesystem_now() - first_stat.st_mtime < self.stale_lock_seconds:\n            return False\n\n        first_token = self._lock_token()\n        if self._local_lock_owner_alive(first_token):\n            return False\n        time.sleep(DEFAULT_LOCK_SETTLE_SECONDS)\n        try:\n            second_stat = self.lock_path.lstat()\n        except OSError:\n            return False\n        if (\n            second_stat.st_dev != first_stat.st_dev\n            or second_stat.st_ino != first_stat.st_ino\n            or second_stat.st_mtime_ns != first_stat.st_mtime_ns\n        ):\n            return False\n        second_token = self._lock_token()\n        if second_token != first_token or self._local_lock_owner_alive(second_token):\n            return False\n        return self._filesystem_now() - second_stat.st_mtime >= self.stale_lock_seconds\n'''
py = replace_once(py, old, new, "python stale lock")
old = '''    def _load_unlocked(self) -> WorkGraph:\n        if not self.state_path.exists():\n            return WorkGraph(self.repo_id)\n        if self.state_path.is_symlink():\n            raise WorkGraphStateError(f"refusing symlink Work Graph state: {self.state_path}")\n        flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)\n        try:\n            fd = os.open(self.state_path, flags)\n        except FileNotFoundError:\n            return WorkGraph(self.repo_id)\n        except OSError as exc:\n            raise WorkGraphStateError(f"cannot open Work Graph state safely: {exc}") from exc\n        try:\n            stat = os.fstat(fd)\n            if stat.st_size > self.max_state_bytes:\n                raise WorkGraphStateError(\n                    f"Work Graph state is {stat.st_size} bytes; limit is {self.max_state_bytes}"\n                )\n            payload = bytearray()\n            while len(payload) <= self.max_state_bytes:\n                chunk = os.read(fd, min(1024 * 1024, self.max_state_bytes + 1 - len(payload)))\n                if not chunk:\n                    break\n                payload.extend(chunk)\n            if len(payload) > self.max_state_bytes:\n                raise WorkGraphStateError(f"Work Graph state exceeds {self.max_state_bytes} bytes")\n        finally:\n            os.close(fd)\n        try:\n            graph = WorkGraph.from_json(bytes(payload).decode("utf-8"))\n'''
new = '''    def _load_unlocked(self) -> WorkGraph:\n        payload = self._read_regular_file_bounded(\n            self.state_path, self.max_state_bytes, "state"\n        )\n        if payload is None:\n            return WorkGraph(self.repo_id)\n        try:\n            graph = WorkGraph.from_json(payload.decode("utf-8"))\n'''
py = replace_once(py, old, new, "python state read")
py = replace_once(
    py,
    '''            os.replace(temp_path, self.state_path)\n            if os.name == "posix":\n                self.state_path.chmod(0o600)\n            _fsync_dir(self.repo_dir)\n''',
    '''            # mkstemp created the file with private permissions. Rename preserves\n            # those permissions; avoiding a post-rename pathname chmod closes a\n            # same-user symlink-swap window.\n            os.replace(temp_path, self.state_path)\n            _fsync_dir(self.repo_dir)\n''',
    "python post rename chmod",
)
py_path.write_text(py, encoding="utf-8")

js_path = Path("entroly-wasm/js/work_graph_store.js")
js = js_path.read_text(encoding="utf-8")
js = replace_once(
    js,
    "const DEFAULT_MAX_STATE_BYTES = 64 * 1024 * 1024;\n",
    "const DEFAULT_MAX_STATE_BYTES = 64 * 1024 * 1024;\nconst MAX_LOCK_FILE_BYTES = 4096;\n",
    "node lock bound",
)
anchor = '''function fsyncDirectory(dir) {\n  if (process.platform === 'win32') return;\n  let fd;\n  try {\n    fd = fs.openSync(dir, fs.constants.O_RDONLY);\n    fs.fsyncSync(fd);\n  } catch (_) {\n    // File fsync + atomic rename remain the primary durability guarantee.\n  } finally {\n    if (fd !== undefined) fs.closeSync(fd);\n  }\n}\n'''
helper = anchor + '''\nfunction sameFileIdentity(left, right) {\n  return left.dev === right.dev && left.ino === right.ino;\n}\n\nfunction readRegularFileBounded(filePath, maxBytes, label) {\n  let expected;\n  try { expected = fs.lstatSync(filePath, { bigint: true }); }\n  catch (error) {\n    if (error && error.code === 'ENOENT') return null;\n    throw new WorkGraphStateError(`cannot inspect Work Graph ${label}: ${error.message}`);\n  }\n  if (expected.isSymbolicLink() || !expected.isFile()) {\n    throw new WorkGraphStateError(`unsafe Work Graph ${label}: ${filePath}`);\n  }\n  if (expected.size > BigInt(maxBytes)) {\n    throw new WorkGraphStateError(`Work Graph ${label} is ${expected.size} bytes; limit is ${maxBytes}`);\n  }\n\n  const noFollow = fs.constants.O_NOFOLLOW || 0;\n  let fd;\n  try {\n    fd = fs.openSync(filePath, fs.constants.O_RDONLY | noFollow);\n    const before = fs.fstatSync(fd, { bigint: true });\n    if (!before.isFile() || !sameFileIdentity(expected, before)) {\n      throw new WorkGraphStateError(`Work Graph ${label} changed while opening: ${filePath}`);\n    }\n    if (before.size > BigInt(maxBytes)) {\n      throw new WorkGraphStateError(`Work Graph ${label} is ${before.size} bytes; limit is ${maxBytes}`);\n    }\n\n    const chunks = [];\n    let total = 0;\n    const scratch = Buffer.allocUnsafe(Math.min(1024 * 1024, maxBytes + 1));\n    for (;;) {\n      const remaining = maxBytes + 1 - total;\n      if (remaining <= 0) break;\n      const count = fs.readSync(fd, scratch, 0, Math.min(scratch.length, remaining), null);\n      if (count === 0) break;\n      chunks.push(Buffer.from(scratch.subarray(0, count)));\n      total += count;\n    }\n    if (total > maxBytes) {\n      throw new WorkGraphStateError(`Work Graph ${label} exceeds ${maxBytes} bytes`);\n    }\n\n    const after = fs.fstatSync(fd, { bigint: true });\n    if (\n      !sameFileIdentity(before, after)\n      || before.size !== after.size\n      || before.mtimeNs !== after.mtimeNs\n      || before.ctimeNs !== after.ctimeNs\n    ) {\n      throw new WorkGraphStateError(`Work Graph ${label} changed during read: ${filePath}`);\n    }\n    const current = fs.lstatSync(filePath, { bigint: true });\n    if (!sameFileIdentity(before, current) || current.isSymbolicLink() || !current.isFile()) {\n      throw new WorkGraphStateError(`Work Graph ${label} path changed during read: ${filePath}`);\n    }\n    return Buffer.concat(chunks, total);\n  } catch (error) {\n    if (error instanceof WorkGraphStateError) throw error;\n    if (error && error.code === 'ENOENT') return null;\n    throw new WorkGraphStateError(`cannot read Work Graph ${label} safely: ${error.message}`);\n  } finally {\n    if (fd !== undefined) { try { fs.closeSync(fd); } catch (_) {} }\n  }\n}\n\nfunction localLockOwnerAlive(token) {\n  const parts = String(token || '').split(':');\n  if (parts.length < 3) return false;\n  const uuid = parts.pop();\n  const pidText = parts.pop();\n  const host = parts.join(':');\n  if (!uuid || host !== os.hostname()) return false;\n  const pid = Number(pidText);\n  if (!Number.isSafeInteger(pid) || pid <= 0) return false;\n  if (pid === process.pid) return true;\n  try { process.kill(pid, 0); return true; }\n  catch (error) {\n    if (error && error.code === 'EPERM') return true;\n    return false;\n  }\n}\n'''
js = replace_once(js, anchor, helper, "node safe reader helpers")
old = '''  readLockToken() {\n    try {\n      const stat = fs.lstatSync(this.lockPath);\n      if (stat.isSymbolicLink() || !stat.isFile()) {\n        throw new WorkGraphStateError(`unsafe Work Graph lock path: ${this.lockPath}`);\n      }\n      return fs.readFileSync(this.lockPath, 'utf8').split('\\n', 1)[0];\n    } catch (error) {\n      if (error instanceof WorkGraphStateError) throw error;\n      return '';\n    }\n  }\n'''
new = '''  readLockToken() {\n    const payload = readRegularFileBounded(this.lockPath, MAX_LOCK_FILE_BYTES, 'lock');\n    if (payload == null) return '';\n    return payload.toString('utf8').split('\\n', 1)[0];\n  }\n'''
js = replace_once(js, old, new, "node lock read")
old = '''  lockIsStale() {\n    let stat;\n    try { stat = fs.lstatSync(this.lockPath); }\n    catch (_) { return false; }\n    if (stat.isSymbolicLink() || !stat.isFile()) {\n      throw new WorkGraphStateError(`unsafe Work Graph lock path: ${this.lockPath}`);\n    }\n    const first = stat.mtimeMs;\n    if (this.filesystemNowMs() - first < this.staleLockMs) return false;\n    sleepMs(DEFAULT_LOCK_SETTLE_MS);\n    let second;\n    try { second = fs.statSync(this.lockPath).mtimeMs; }\n    catch (_) { return false; }\n    return second === first && this.filesystemNowMs() - second >= this.staleLockMs;\n  }\n'''
new = '''  lockIsStale() {\n    let first;\n    try { first = fs.lstatSync(this.lockPath, { bigint: true }); }\n    catch (_) { return false; }\n    if (first.isSymbolicLink() || !first.isFile()) {\n      throw new WorkGraphStateError(`unsafe Work Graph lock path: ${this.lockPath}`);\n    }\n    if (this.filesystemNowMs() - Number(first.mtimeMs) < this.staleLockMs) return false;\n    const firstToken = this.readLockToken();\n    if (localLockOwnerAlive(firstToken)) return false;\n    sleepMs(DEFAULT_LOCK_SETTLE_MS);\n    let second;\n    try { second = fs.lstatSync(this.lockPath, { bigint: true }); }\n    catch (_) { return false; }\n    if (!sameFileIdentity(first, second) || first.mtimeNs !== second.mtimeNs) return false;\n    const secondToken = this.readLockToken();\n    if (secondToken !== firstToken || localLockOwnerAlive(secondToken)) return false;\n    return this.filesystemNowMs() - Number(second.mtimeMs) >= this.staleLockMs;\n  }\n'''
js = replace_once(js, old, new, "node stale lock")
old = '''  loadUnlocked() {\n    if (!fs.existsSync(this.statePath)) return new WorkGraph(this.repoId);\n    const stat = fs.lstatSync(this.statePath);\n    if (stat.isSymbolicLink() || !stat.isFile()) {\n      throw new WorkGraphStateError(`unsafe Work Graph state: ${this.statePath}`);\n    }\n    if (stat.size > this.maxStateBytes) {\n      throw new WorkGraphStateError(`Work Graph state is ${stat.size} bytes; limit is ${this.maxStateBytes}`);\n    }\n    let graph;\n    try { graph = WorkGraph.fromJSON(fs.readFileSync(this.statePath, 'utf8')); }\n    catch (error) { throw new WorkGraphStateError(`cannot load Work Graph state: ${error.message}`); }\n'''
new = '''  loadUnlocked() {\n    const payload = readRegularFileBounded(this.statePath, this.maxStateBytes, 'state');\n    if (payload == null) return new WorkGraph(this.repoId);\n    let graph;\n    try { graph = WorkGraph.fromJSON(payload.toString('utf8')); }\n    catch (error) { throw new WorkGraphStateError(`cannot load Work Graph state: ${error.message}`); }\n'''
js = replace_once(js, old, new, "node state read")
js = replace_once(
    js,
    '''      fs.renameSync(temp, this.statePath);\n      if (process.platform !== 'win32') fs.chmodSync(this.statePath, 0o600);\n      fsyncDirectory(this.repoDir);\n''',
    '''      // The temporary file was created 0600. Rename preserves its mode;\n      // avoid a pathname chmod after rename, which would reopen a swap window.\n      fs.renameSync(temp, this.statePath);\n      fsyncDirectory(this.repoDir);\n''',
    "node post rename chmod",
)
js_path.write_text(js, encoding="utf-8")

print("store race hardening patch applied")
